"""Visual local TradeDesk for supervised DEMO observation and replay."""

from __future__ import annotations


def tradedesk_html() -> str:
    """Return the local investor view; it never exposes broker controls."""
    return """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ODIN TradeDesk</title><style>
:root{color-scheme:dark;--bg:#09111d;--panel:#111f31;--line:#29425f;--text:#e8f2ff;--muted:#8fa7c4;--ok:#41d69a;--warn:#ffc857;--bad:#ff7180}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,sans-serif}header{padding:18px 28px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}h1{margin:0;font-size:24px}.tag{padding:5px 9px;border:1px solid var(--line);border-radius:99px;color:var(--muted)}a{color:#8fc9ff}.layout{max-width:1500px;margin:auto;padding:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.card,.panel{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:14px}.label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.value{font-size:20px;font-weight:650;margin-top:7px;overflow-wrap:anywhere}.ok{color:var(--ok)}.warn{color:var(--warn)}.bad{color:var(--bad)}.two{display:grid;grid-template-columns:minmax(0,2fr) minmax(320px,1fr);gap:14px;margin-top:14px}svg{width:100%;height:300px;background:#0a1726;border-radius:8px}table{width:100%;border-collapse:collapse}td,th{padding:9px;text-align:left;border-bottom:1px solid var(--line);font-size:12px}th{color:var(--muted)}section{margin-top:14px}small{color:var(--muted)}pre{overflow:auto;white-space:pre-wrap}input,button{background:#0a1726;border:1px solid var(--line);border-radius:5px;color:var(--text);padding:6px}button{cursor:pointer}
</style></head><body><header><div><h1>ODIN TradeDesk</h1><small>MT5 DEMO observation + local replay · execution blocked</small></div><div><a href="/cockpit">Technical cockpit</a> <span class="tag" id="stamp">loading</span></div></header>
<main class="layout"><div class="grid" id="account"></div><div class="two"><section class="panel"><div class="label" id="market-title">Market</div><svg viewBox="0 0 800 300"><polyline id="line" fill="none" stroke="#41d69a" stroke-width="3"/></svg><small id="market-note"></small></section><section class="panel"><div class="label">ODIN state</div><div class="value warn" id="odin">loading</div><p id="reason"></p><div class="label">Risk</div><pre id="risk"></pre></section></div>
<section class="panel"><div class="label">MT5 DEMO open positions · read-only</div><table id="mt5-positions"></table></section><section class="panel"><div class="label">Replay open positions · simulated</div><table id="positions"></table></section><section class="panel"><div class="label">Closed replay operations · simulated</div><table id="orders"></table></section><section class="panel"><div class="label">ODIN decision journal · replay evidence</div><table id="journal"></table></section><section class="panel"><div class="label">Hermes local diagnostic · read-only</div><small>Operational diagnosis and data provenance; it does not produce a trading recommendation.</small><pre id="hermes">loading...</pre></section>
<section class="panel"><div class="label">Replay preferences</div><small>Local simulation only. These settings never connect a broker or enable execution.</small><form id="config"><p><label>Watchlist (comma-separated permitted FX pairs) <input id="watchlist" value="EURUSD"></label></p><p><label>Daily loss limit EUR <input id="daily" type="number" min="10" max="500" value="100"></label> <label>Risk per replay EUR <input id="trade-risk" type="number" min="1" max="500" value="25"></label> <label>Maximum replay lots <input id="lots" type="number" min="0.01" max="0.10" step="0.01" value="0.05"></label></p><button type="submit">Save replay preferences</button> <small id="config-status"></small></form></section></main>
<script>
const money=(n,currency='EUR')=>new Intl.NumberFormat('en',{style:'currency',currency:currency||'EUR'}).format(Number(n||0));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const table=(id,heads,rows)=>document.getElementById(id).innerHTML='<tr>'+heads.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr>'+rows.map(row=>'<tr>'+row.map(cell=>'<td>'+esc(cell)+'</td>').join('')+'</tr>').join('');
const draw=candles=>{const values=candles.map(c=>Number(c.close)).filter(Number.isFinite);if(values.length<2)return;const low=Math.min(...values),high=Math.max(...values),span=high-low||1;document.getElementById('line').setAttribute('points',values.map((v,i)=>(i/(values.length-1)*780+10).toFixed(1)+','+(280-(v-low)/span*250).toFixed(1)).join(' '));};
fetch('/trading/replay').then(r=>r.json()).then(d=>{const a=d.account,live=d.mt5_demo.market||{},liveOk=d.mt5_demo.status==='CONNECTED_DEMO_READ_ONLY'&&live.status==='OK',mt5Currency=d.mt5_demo.account.currency||'EUR',price=liveOk?Number(live.bid).toFixed(5)+' / '+Number(live.ask).toFixed(5):'unavailable';const cards=[['Replay balance',money(a.balance),'ok'],['Replay equity',money(a.equity),'ok'],['Replay P/L today',money(a.daily_profit),'ok'],['Replay drawdown',a.drawdown_percent+'%','warn'],['Public data',d.public_data.status||'UNKNOWN',d.public_data.status==='OK'?'ok':'warn'],['Data fresh',String(d.public_data.fresh),d.public_data.fresh?'ok':'warn'],['Execution',String(d.execution_allowed),'bad'],['MT5 DEMO',d.mt5_demo.status,d.mt5_demo.status==='CONNECTED_DEMO_READ_ONLY'?'ok':'warn'],['MT5 account equity',d.mt5_demo.account.equity===undefined?'n/a':money(d.mt5_demo.account.equity,mt5Currency),liveOk?'ok':'warn'],['MT5 EURUSD',price,liveOk?'ok':'warn'],['MT5 quote time',live.as_of||'n/a',liveOk?'ok':'warn']];document.getElementById('account').innerHTML=cards.map(x=>'<div class="card"><div class="label">'+esc(x[0])+'</div><div class="value '+x[2]+'">'+esc(x[1])+'</div></div>').join('');const chart=liveOk&&Array.isArray(live.candles)&&live.candles.length>1?live:{symbol:d.market.symbol,timeframe:d.market.timeframe,candles:d.market.candles};draw(chart.candles);document.getElementById('market-title').textContent=chart.symbol+' · '+(liveOk?'MT5 DEMO M15':'local replay '+chart.timeframe);document.getElementById('market-note').textContent=liveOk?'Current terminal observation; read-only, not a trading signal.':'Replay data; terminal price is unavailable.';document.getElementById('odin').textContent=d.odin.state+' · Net replay P/L '+money(d.metrics.net_profit)+' · Win rate '+d.metrics.win_rate_percent+'%';document.getElementById('reason').textContent=d.odin.reason;document.getElementById('risk').textContent=JSON.stringify(d.risk,null,2);table('mt5-positions',['Pair','Side','Volume','P/L'],(d.mt5_demo.positions||[]).map(p=>[p.symbol,p.type,p.volume,money(p.profit,mt5Currency)]));table('positions',['Ticket','Pair','Side','Volume','Entry','Mark','P/L'],d.positions.map(p=>[p.ticket,p.symbol,p.side,p.volume,p.entry,p.mark,money(p.profit)]));table('orders',['Ticket','Pair','Side','Status','Opened','Closed','P/L'],d.orders.map(o=>[o.ticket,o.symbol,o.side,o.status,o.opened_at,o.closed_at,money(o.profit)]));table('journal',['ID','Pair','State','Context','Entry','Stop','Target','Risk','Reason','Outcome'],d.decision_journal.map(j=>[j.id,j.symbol,j.state,j.context,j.entry,j.stop_loss,j.take_profit,money(j.risk),j.reason,j.outcome]));const cfg=d.configuration;document.getElementById('watchlist').value=cfg.watchlist.join(', ');document.getElementById('daily').value=cfg.risk_limits.daily_loss_limit;document.getElementById('trade-risk').value=cfg.risk_limits.per_trade_risk_limit;document.getElementById('lots').value=cfg.risk_limits.max_position_lots;document.getElementById('stamp').textContent='updated '+new Date().toLocaleTimeString();}).catch(e=>document.getElementById('stamp').textContent='error '+e.message);
document.getElementById('config').addEventListener('submit',e=>{e.preventDefault();const value={watchlist:document.getElementById('watchlist').value.split(',').map(x=>x.trim()).filter(Boolean),risk_limits:{daily_loss_limit:Number(document.getElementById('daily').value),per_trade_risk_limit:Number(document.getElementById('trade-risk').value),max_position_lots:Number(document.getElementById('lots').value)}};fetch('/trading/replay/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)}).then(r=>r.json().then(p=>({ok:r.ok,p}))).then(x=>document.getElementById('config-status').textContent=x.ok?'saved locally; execution remains blocked':'blocked: '+x.p.reason).catch(err=>document.getElementById('config-status').textContent='error: '+err.message);});
fetch('/hermes/summary').then(r=>r.json()).then(h=>{document.getElementById('hermes').textContent=JSON.stringify({status:h.status,mode:h.hermes_mode,read_only:h.read_only,summary:h.summary,market_evidence:h.market_evidence,critical_warnings:h.critical_warnings},null,2)}).catch(e=>document.getElementById('hermes').textContent='Hermes unavailable: '+e.message);
	</script></body></html>"""
